import { loadStripe, type Stripe } from '@stripe/stripe-js'
import StripeNode from 'stripe'

let stripePromise: Promise<Stripe | null>

export const getStripe = (): Promise<Stripe | null> => {
  if (!stripePromise) {
    stripePromise = loadStripe(import.meta.env.PUBLIC_STRIPE_PUBLISHABLE_KEY!)
  }
  return stripePromise
}

// Server-side Stripe client
export const stripe = new StripeNode(import.meta.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2024-12-18.acacia'
})

import type Stripe from 'stripe'

// Re-export Stripe types for convenience
export type {
  Stripe,
  StripeError,
  PaymentIntent,
  PaymentMethod,
  Customer,
  Subscription,
  Price,
  Product as StripeProduct,
  Webhook,
  Event as StripeEvent
} from 'stripe'

// Custom Stripe-related types
export interface PaymentIntentData {
  amount: number
  currency: string
  customerId?: string
  metadata?: Record<string, string>
}

export interface CreateCustomerData {
  email: string
  name?: string
  metadata?: Record<string, string>
}

export interface WebhookEventData {
  id: string
  object: string
  type: string
  data: {
    object: any
  }
}

