// API endpoint: /api/payments/create-intent
import type { APIRoute } from 'astro'
import { stripe } from '@/lib/stripe'
import { z } from 'zod'

const createPaymentSchema = z.object({
  amount: z.number().min(50), // $0.50 minimum
  currency: z.string().default('usd'),
